SCHEMA = 'CREATE TABLE mcp_servers (\n            id TEXT PRIMARY KEY, name TEXT NOT NULL, server_config TEXT NOT NULL,\n            description TEXT, homepage TEXT, docs TEXT, tags TEXT NOT NULL DEFAULT \'[]\',\n            enabled_claude BOOLEAN NOT NULL DEFAULT 0, enabled_codex BOOLEAN NOT NULL DEFAULT 0,\n            enabled_gemini BOOLEAN NOT NULL DEFAULT 0, enabled_opencode BOOLEAN NOT NULL DEFAULT 0\n        , "enabled_hermes" BOOLEAN NOT NULL DEFAULT 0, "enabled_grokbuild" BOOLEAN NOT NULL DEFAULT 0, "enabled_mcode" BOOLEAN NOT NULL DEFAULT 0, "enabled_pi" BOOLEAN NOT NULL DEFAULT 0);\nCREATE TABLE model_pricing (\n            model_id TEXT PRIMARY KEY, display_name TEXT NOT NULL,\n            input_cost_per_million TEXT NOT NULL, output_cost_per_million TEXT NOT NULL,\n            cache_read_cost_per_million TEXT NOT NULL DEFAULT \'0\',\n            cache_creation_cost_per_million TEXT NOT NULL DEFAULT \'0\'\n        );\nCREATE TABLE profiles (\n                id TEXT PRIMARY KEY,\n                name TEXT NOT NULL,\n                payload TEXT NOT NULL,\n                sort_order INTEGER,\n                created_at INTEGER,\n                updated_at INTEGER\n            );\nCREATE TABLE prompts (\n            id TEXT NOT NULL, app_type TEXT NOT NULL, name TEXT NOT NULL, content TEXT NOT NULL,\n            description TEXT, enabled BOOLEAN NOT NULL DEFAULT 1, created_at INTEGER, updated_at INTEGER,\n            PRIMARY KEY (id, app_type)\n        );\nCREATE TABLE provider_endpoints (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                provider_id TEXT NOT NULL,\n                app_type TEXT NOT NULL,\n                url TEXT NOT NULL,\n                added_at INTEGER,\n                FOREIGN KEY (provider_id, app_type) REFERENCES providers(id, app_type) ON DELETE CASCADE\n            );\nCREATE TABLE provider_health (\n            provider_id TEXT NOT NULL, app_type TEXT NOT NULL, is_healthy INTEGER NOT NULL DEFAULT 1,\n            consecutive_failures INTEGER NOT NULL DEFAULT 0, last_success_at TEXT, last_failure_at TEXT,\n            last_error TEXT, updated_at TEXT NOT NULL,\n            PRIMARY KEY (provider_id, app_type),\n            FOREIGN KEY (provider_id, app_type) REFERENCES providers(id, app_type) ON DELETE CASCADE\n        );\nCREATE TABLE providers (\n                id TEXT NOT NULL,\n                app_type TEXT NOT NULL,\n                name TEXT NOT NULL,\n                settings_config TEXT NOT NULL,\n                website_url TEXT,\n                category TEXT,\n                created_at INTEGER,\n                sort_index INTEGER,\n                notes TEXT,\n                icon TEXT,\n                icon_color TEXT,\n                meta TEXT NOT NULL DEFAULT \'{}\',\n                is_current BOOLEAN NOT NULL DEFAULT 0,\n                in_failover_queue BOOLEAN NOT NULL DEFAULT 0, "cost_multiplier" TEXT NOT NULL DEFAULT \'1.0\', "limit_daily_usd" TEXT, "limit_monthly_usd" TEXT, "provider_type" TEXT,\n                PRIMARY KEY (id, app_type)\n            );\nCREATE TABLE "proxy_config" (\n                app_type TEXT PRIMARY KEY CHECK (app_type IN (\'claude\',\'codex\',\'gemini\',\'grokbuild\')),\n                proxy_enabled INTEGER NOT NULL DEFAULT 0,\n                listen_address TEXT NOT NULL DEFAULT \'127.0.0.1\',\n                listen_port INTEGER NOT NULL DEFAULT 15721,\n                enable_logging INTEGER NOT NULL DEFAULT 1,\n                enabled INTEGER NOT NULL DEFAULT 0,\n                auto_failover_enabled INTEGER NOT NULL DEFAULT 0,\n                max_retries INTEGER NOT NULL DEFAULT 3,\n                streaming_first_byte_timeout INTEGER NOT NULL DEFAULT 60,\n                streaming_idle_timeout INTEGER NOT NULL DEFAULT 120,\n                non_streaming_timeout INTEGER NOT NULL DEFAULT 600,\n                circuit_failure_threshold INTEGER NOT NULL DEFAULT 4,\n                circuit_success_threshold INTEGER NOT NULL DEFAULT 2,\n                circuit_timeout_seconds INTEGER NOT NULL DEFAULT 60,\n                circuit_error_rate_threshold REAL NOT NULL DEFAULT 0.6,\n                circuit_min_requests INTEGER NOT NULL DEFAULT 10,\n                default_cost_multiplier TEXT NOT NULL DEFAULT \'1\',\n                pricing_model_source TEXT NOT NULL DEFAULT \'response\',\n                live_takeover_active INTEGER NOT NULL DEFAULT 0,\n                created_at TEXT NOT NULL DEFAULT (datetime(\'now\')),\n                updated_at TEXT NOT NULL DEFAULT (datetime(\'now\'))\n            );\nCREATE TABLE proxy_live_backup (\n            app_type TEXT PRIMARY KEY, original_config TEXT NOT NULL, backed_up_at TEXT NOT NULL\n        );\nCREATE TABLE proxy_request_logs (\n            request_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, app_type TEXT NOT NULL, model TEXT NOT NULL,\n            request_model TEXT,\n            input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0,\n            cache_read_tokens INTEGER NOT NULL DEFAULT 0, cache_creation_tokens INTEGER NOT NULL DEFAULT 0,\n            input_cost_usd TEXT NOT NULL DEFAULT \'0\', output_cost_usd TEXT NOT NULL DEFAULT \'0\',\n            cache_read_cost_usd TEXT NOT NULL DEFAULT \'0\', cache_creation_cost_usd TEXT NOT NULL DEFAULT \'0\',\n            total_cost_usd TEXT NOT NULL DEFAULT \'0\', latency_ms INTEGER NOT NULL, first_token_ms INTEGER,\n            duration_ms INTEGER, status_code INTEGER NOT NULL, error_message TEXT, session_id TEXT,\n            provider_type TEXT, is_streaming INTEGER NOT NULL DEFAULT 0,\n            cost_multiplier TEXT NOT NULL DEFAULT \'1.0\', created_at INTEGER NOT NULL,\n            data_source TEXT NOT NULL DEFAULT \'proxy\'\n        , "pricing_model" TEXT, "input_token_semantics" INTEGER NOT NULL DEFAULT 0);\nCREATE TABLE session_log_sync (\n                file_path TEXT PRIMARY KEY,\n                last_modified INTEGER NOT NULL,\n                last_line_offset INTEGER NOT NULL DEFAULT 0,\n                last_synced_at INTEGER NOT NULL\n            , "last_byte_offset" INTEGER, "last_tail_fingerprint" INTEGER);\nCREATE TABLE session_usage_dedup (\n                data_source TEXT NOT NULL,\n                request_id TEXT NOT NULL,\n                semantic_id TEXT NOT NULL,\n                has_entry_id INTEGER NOT NULL DEFAULT 0,\n                PRIMARY KEY (data_source, request_id)\n            );\nCREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);\nCREATE TABLE skill_repos (\n            owner TEXT NOT NULL, name TEXT NOT NULL, branch TEXT NOT NULL DEFAULT \'main\',\n            enabled BOOLEAN NOT NULL DEFAULT 1, PRIMARY KEY (owner, name)\n        );\nCREATE TABLE skills (\n            id TEXT PRIMARY KEY,\n            name TEXT NOT NULL,\n            description TEXT,\n            directory TEXT NOT NULL,\n            repo_owner TEXT,\n            repo_name TEXT,\n            repo_branch TEXT DEFAULT \'main\',\n            readme_url TEXT,\n            enabled_claude BOOLEAN NOT NULL DEFAULT 0,\n            enabled_codex BOOLEAN NOT NULL DEFAULT 0,\n            enabled_gemini BOOLEAN NOT NULL DEFAULT 0,\n            enabled_opencode BOOLEAN NOT NULL DEFAULT 0,\n            installed_at INTEGER NOT NULL DEFAULT 0,\n            content_hash TEXT,\n            updated_at INTEGER NOT NULL DEFAULT 0\n        , "enabled_hermes" BOOLEAN NOT NULL DEFAULT 0, "enabled_grokbuild" BOOLEAN NOT NULL DEFAULT 0, "enabled_mcode" BOOLEAN NOT NULL DEFAULT 0);\nCREATE TABLE stream_check_logs (\n            id INTEGER PRIMARY KEY AUTOINCREMENT, provider_id TEXT NOT NULL, provider_name TEXT NOT NULL,\n            app_type TEXT NOT NULL, status TEXT NOT NULL, success INTEGER NOT NULL, message TEXT NOT NULL,\n            response_time_ms INTEGER, http_status INTEGER, model_used TEXT,\n            retry_count INTEGER DEFAULT 0, tested_at INTEGER NOT NULL\n        );\nCREATE TABLE usage_daily_rollups (\n                 date TEXT NOT NULL,\n                 app_type TEXT NOT NULL,\n                 provider_id TEXT NOT NULL,\n                 model TEXT NOT NULL,\n                 request_model TEXT NOT NULL DEFAULT \'\',\n                 pricing_model TEXT NOT NULL DEFAULT \'\',\n                 request_count INTEGER NOT NULL DEFAULT 0,\n                 success_count INTEGER NOT NULL DEFAULT 0,\n                 input_tokens INTEGER NOT NULL DEFAULT 0,\n                 output_tokens INTEGER NOT NULL DEFAULT 0,\n                 cache_read_tokens INTEGER NOT NULL DEFAULT 0,\n                 cache_creation_tokens INTEGER NOT NULL DEFAULT 0,\n                 total_cost_usd TEXT NOT NULL DEFAULT \'0\',\n                 avg_latency_ms INTEGER NOT NULL DEFAULT 0, "input_token_semantics" INTEGER NOT NULL DEFAULT 0,\n                 PRIMARY KEY (date, app_type, provider_id, model, request_model, pricing_model)\n             );\nCREATE INDEX idx_providers_failover\n             ON providers(app_type, in_failover_queue, sort_index);\nCREATE INDEX idx_request_logs_app_created_at\n                 ON proxy_request_logs(app_type, created_at DESC);\nCREATE INDEX idx_request_logs_created_at ON proxy_request_logs(created_at);\nCREATE INDEX idx_request_logs_dedup_lookup_expr\n             ON proxy_request_logs(app_type, COALESCE(data_source, \'proxy\'), input_tokens,\n                                   output_tokens, cache_read_tokens, created_at,\n                                   cache_creation_tokens);\nCREATE INDEX idx_request_logs_model ON proxy_request_logs(model);\nCREATE INDEX idx_request_logs_provider ON proxy_request_logs(provider_id, app_type);\nCREATE INDEX idx_request_logs_session ON proxy_request_logs(session_id);\nCREATE INDEX idx_request_logs_status ON proxy_request_logs(status_code);\nCREATE INDEX idx_session_usage_dedup_semantic\n             ON session_usage_dedup(data_source, semantic_id, has_entry_id);\nCREATE INDEX idx_stream_check_logs_provider\n             ON stream_check_logs(app_type, provider_id, tested_at DESC);\n'
